def _domain(declared):
    required = {'kind', 'opted_in_law', 'units', 'domain', 'seed_policy', 'connectivity_policy', 'rounding_policy', 'physical_status'}
    if not isinstance(declared, Mapping) or set(declared) != required:
        raise ValueError('Declare the complete fixed-seed/domain/connectivity law')
    if declared['kind'] != INPUT_KIND or declared['opted_in_law'] != LAW_ID or declared['units'] != UNITS or (declared['seed_policy'] != 'retain_original_binary64_coordinates_and_owner_ids') or (declared['connectivity_policy'] != 'replace_dual_and_seed_adjacency_explicitly') or (declared['rounding_policy'] != 'shared_vertex_once_strict_domain_no_collision_or_seed_loss') or (declared['physical_status'] != 'prospective_geometry_only_no_physical_admission'):
        raise ValueError('Unsupported geometry law, units, seed move or physical promotion')
    domain = declared['domain']
    if not isinstance(domain, Mapping) or set(domain) != {'id', 'vertices_m', 'provenance', 'role'} or type(domain['id']) is not str or (not domain['id']) or (domain['role'] != 'prospective_partition_envelope_not_native_tissue_boundary'):
        raise ValueError('Supply an explicit finite convex envelope and its geometric role')
    source = domain['provenance']
    if not isinstance(source, Mapping) or set(source) != {'kind', 'authority', 'document_sha256', 'field', 'native_tissue_equivalence'} or source['kind'] != 'explicit_caller_polygon@1' or any((type(source[key]) is not str or not source[key] for key in ('authority', 'field'))) or (type(source['document_sha256']) is not str) or (len(source['document_sha256']) != 64) or any((c not in '0123456789abcdef' for c in source['document_sha256'])) or (source['native_tissue_equivalence'] is not False):
        raise ValueError('No default domain: record caller authority and original document/field')
    points = domain['vertices_m']
    if not isinstance(points, (tuple, list)) or not 3 <= len(points) <= MAX_DOMAIN_VERTICES:
        raise ValueError('Outside the bounded explicit domain vertex axis')
    exact = tuple((_binary_point(row) for row in points))
    if len(set(exact)) != len(exact):
        raise ValueError('Repeated domain vertex')
    if any((polygons._orient(exact[i - 1], exact[i], exact[(i + 1) % len(exact)]) <= 0 for i in range(len(exact)))):
        raise ValueError('Require a strictly convex CCW caller domain, without collinear corners')
    polygons._complex(dict(enumerate(exact)), [dict(id='declared-domain', vertex_ids=list(range(len(exact))))], stage='declared_domain')
    return exact

independent_stored_geometry_admission.expression:
def admit(vertices, rings, seeds, domain):
    """Convex separating axes, global segment owners and domain interval cover."""
    if len(set(vertices)) != len(vertices):
        raise ValueError('Independent rounded shared vertices collided')
    owner_edges, metrics = ({}, [])
    polygons = [[vertices[index] for index in ring] for ring in rings]
    for owner, poly in enumerate(polygons):
        if len(poly) < 3 or len(set(rings[owner])) != len(poly):
            raise ValueError('Independent simple nonempty cell axis required')
        metrics.append(moments(poly))
        for local, b in enumerate(rings[owner]):
            a = rings[owner][local - 1]
            if any((turn(vertices[a], vertices[b], p) < 0 for p in poly)):
                raise ValueError('Independent shared geometry lost CCW convexity')
            if turn(vertices[a], vertices[b], seeds[owner]) <= 0:
                raise ValueError('Independent strict seed containment failed')
            owner_edges.setdefault(tuple(sorted((a, b))), []).append((owner, a, b))
    for left, poly in enumerate(polygons):
        for other in polygons[left + 1:]:
            separated = False
            for shape in (poly, other):
                for i, b in enumerate(shape):
                    a = shape[i - 1]
                    axis = (b[1] - a[1], a[0] - b[0])
                    first = [axis[0] * p[0] + axis[1] * p[1] for p in poly]
                    second = [axis[0] * p[0] + axis[1] * p[1] for p in other]
                    if max(first) <= min(second) or max(second) <= min(first):
                        separated = True
                        break
                if separated:
                    break
            if not separated:
                raise ValueError('Independent convex-cell interior overlap')
    for (a, b), owners in owner_edges.items():
        if len(owners) not in (1, 2) or (len(owners) == 2 and owners[0][1:] != tuple(reversed(owners[1][1:]))):
            raise ValueError('Independent shared edge lacks exact opposite ownership')
        if any((index not in (a, b) and on_segment(vertices[a], vertices[b], value) for index, value in enumerate(vertices))):
            raise ValueError('Independent nonconforming vertex inside an unsplit edge')
    if any((turn(domain[i - 1], domain[i], p) < 0 for p in vertices for i in range(len(domain)))):
        raise ValueError('Independent vertex outside declared domain')
    domain_area, domain_centroid = moments(domain)
    if sum((row[0] for row in metrics), Fraction(0)) != domain_area:
        raise ValueError('Independent positive nonoverlapping cell areas leave a domain gap')
    boundary, pieces = ([], [[] for _ in domain])
    for edge, owners in sorted(owner_edges.items()):
        if len(owners) != 1:
            continue
        owner, a, b = owners[0]
        matches = [i for i in range(len(domain)) if on_segment(domain[i - 1], domain[i], vertices[a]) and on_segment(domain[i - 1], domain[i], vertices[b])]
        if len(matches) != 1:
            raise ValueError('Independent boundary left its declared domain segment')
        index = matches[0]
        start, end = (domain[index - 1], domain[index])
        axis = 0 if start[0] != end[0] else 1
        lo, hi = ((vertices[p][axis] - start[axis]) / (end[axis] - start[axis]) for p in (a, b))
        if not 0 <= lo < hi <= 1:
            raise ValueError('Independent boundary orientation/extent')
        pieces[index].append((lo, hi))
        boundary.append(dict(edge=edge, owner=owner, directed=(a, b), domain_edge=index, interval=(lo, hi)))
    for row in pieces:
        end = Fraction(0)
        for lo, hi in sorted(row):
            if lo != end:
                raise ValueError('Independent domain side coverage has a gap or repetition')
            end = hi
        if end != 1:
            raise ValueError('Independent domain side is incomplete')
    return (owner_edges, tuple(metrics), domain_area, domain_centroid, tuple(boundary))

reused_conservative_admission.expression:
def admit_complex(vertices, rings, seeds, domain, *, stage):
    """Use the pinned conservative admission on the actual supplied coordinates."""
    if len(set(vertices)) != len(vertices):
        raise ValueError('Distinct exact vertices collided in the shared coordinate store')
    rows = [dict(id=str(owner), vertex_ids=list(row)) for owner, row in enumerate(rings)]
    incidence, total = polygons._complex(dict(enumerate(vertices)), rows, stage=stage)
    moments = []
    for owner, row in enumerate(rings):
        polygon = [vertices[i] for i in row]
        if any((polygons._orient(polygon[i - 1], polygon[i], polygon[(i + 1) % len(row)]) < 0 for i in range(len(row)))):
            raise ValueError('The shared geometry lost convex cell orientation')
        if polygons._inside(seeds[owner], polygon) != 1:
            raise ValueError('A retained seed is not strictly inside its reconstructed cell')
        moments.append(polygons._moments(polygon))
    for point in vertices:
        if any((polygons._orient(domain[i - 1], domain[i], point) < 0 for i in range(len(domain)))):
            raise ValueError('A reconstructed vertex left the explicitly declared domain')
    domain_area, domain_centroid = polygons._moments(domain)
    if total != domain_area:
        raise ValueError('The nonoverlapping complex does not exactly cover the declared domain area')
    boundary, intervals = ([], [[] for _ in domain])
    for edge, owners in sorted(incidence.items()):
        if len(owners) != 1:
            continue
        owner, a, b = owners[0]
        matches = [i for i in range(len(domain)) if polygons._on(domain[i - 1], domain[i], vertices[a]) and polygons._on(domain[i - 1], domain[i], vertices[b])]
        if len(matches) != 1:
            raise ValueError('A rounded/new boundary segment left its original declared domain edge')
        index = matches[0]
        start, end = (domain[index - 1], domain[index])
        axis = 0 if start[0] != end[0] else 1
        lo, hi = ((vertices[v][axis] - start[axis]) / (end[axis] - start[axis]) for v in (a, b))
        if not 0 <= lo < hi <= 1:
            raise ValueError('Boundary segment orientation or domain parameter changed')
        intervals[index].append((lo, hi))
        boundary.append(dict(edge=edge, owner=owner, directed=(a, b), domain_edge=index, interval=(lo, hi)))
    for row in intervals:
        row.sort()
        previous = Fraction(0)
        for lo, hi in row:
            if lo != previous:
                raise ValueError('Gap or repeated coverage along a declared domain edge')
            previous = hi
        if previous != 1:
            raise ValueError('Incomplete declared domain-edge coverage')
    return (incidence, tuple(moments), domain_area, domain_centroid, tuple(boundary))
